//! Virtual Machine for executing compiled Verilog-A bytecode
//!
//! This module provides a stack-based VM that executes bytecode programs
//! generated by the code generator. It handles voltage/current access,
//! parameter lookup, and mathematical operations.

use crate::codegen::{BytecodeProgram, Instruction, LookupTable};
use crate::laplace::StateSpaceFilter;

/// Execution context providing runtime state to the VM
#[derive(Debug, Clone)]
pub struct VmContext {
    /// Node voltages (indexed by terminal)
    pub voltages: Vec<f64>,
    /// Internal node voltages (for nodes not in port list)
    pub internal_voltages: Vec<f64>,
    /// Branch currents
    pub currents: Vec<f64>,
    /// Terminal-pair branch current lookup table (flattened NxN matrix).
    terminal_pair_currents: Vec<f64>,
    /// Parameter values (indexed by parameter)
    pub parameters: Vec<f64>,
    /// Variable values (indexed by variable)
    pub variables: Vec<f64>,
    /// Current simulation time
    pub time: f64,
    /// Temperature in Kelvin
    pub temperature: f64,
    /// State variable values (current timestep) - for ddt/idt
    pub state_values: Vec<f64>,
    /// State variable values (previous timestep) - for ddt/idt
    pub state_values_prev: Vec<f64>,
    /// Current timestep (delta t) for transient analysis
    pub timestep: f64,
    /// Lookup tables for $table_model interpolation
    pub lookup_tables: Vec<LookupTable>,
    /// Delay buffers for absdelay function
    /// Each buffer stores (time, value) pairs for interpolation
    pub delay_buffers: Vec<DelayBuffer>,
    /// Current analysis type (0=dc, 1=ac, 2=tran, 3=noise)
    pub analysis_type: u8,
    /// Laplace state-space filters
    pub laplace_filters: Vec<StateSpaceFilter>,
}

/// Circular buffer for absdelay transport delay implementation
///
/// Stores a history of (time, value) pairs to enable looking up
/// delayed values via linear interpolation.
#[derive(Debug, Clone)]
pub struct DelayBuffer {
    /// Buffer capacity (max samples)
    capacity: usize,
    /// Circular buffer of (time, value) pairs
    samples: Vec<(f64, f64)>,
    /// Current write position
    write_pos: usize,
    /// Number of samples currently stored
    count: usize,
}

impl DelayBuffer {
    /// Create a new delay buffer with specified capacity
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity: capacity.max(2),
            samples: vec![(0.0, 0.0); capacity.max(2)],
            write_pos: 0,
            count: 0,
        }
    }

    /// Record a sample at the given time
    pub fn record(&mut self, time: f64, value: f64) {
        self.samples[self.write_pos] = (time, value);
        self.write_pos = (self.write_pos + 1) % self.capacity;
        if self.count < self.capacity {
            self.count += 1;
        }
    }

    /// Get the delayed value at (current_time - delay)
    ///
    /// Uses linear interpolation between stored samples.
    /// If delay exceeds buffer history, returns oldest value.
    /// If delay is zero or negative, returns current value (or most recent).
    pub fn get_delayed(&self, current_time: f64, delay: f64) -> f64 {
        if self.count == 0 {
            return 0.0;
        }

        let target_time = current_time - delay;

        // Find the two samples bracketing target_time
        // Samples are stored in circular order, so we need to search
        let mut before: Option<(f64, f64)> = None;
        let mut after: Option<(f64, f64)> = None;

        for i in 0..self.count {
            let idx = if self.count == self.capacity {
                (self.write_pos + i) % self.capacity
            } else {
                i
            };
            let (t, v) = self.samples[idx];

            if t <= target_time {
                before = Some((t, v));
            }
            if t >= target_time && after.is_none() {
                after = Some((t, v));
            }
        }

        match (before, after) {
            (Some((t0, v0)), Some((t1, v1))) if t0 != t1 => {
                // Linear interpolation
                let alpha = (target_time - t0) / (t1 - t0);
                v0 + alpha * (v1 - v0)
            }
            (Some((_, v)), _) => v,
            (_, Some((_, v))) => v,
            _ => 0.0,
        }
    }

    /// Clear the buffer
    pub fn clear(&mut self) {
        self.count = 0;
        self.write_pos = 0;
    }
}

impl Default for DelayBuffer {
    fn default() -> Self {
        Self::new(1024) // Default to 1024 samples
    }
}

/// Transition filter state for piecewise-linear signal smoothing
#[derive(Debug, Clone)]
pub struct TransitionFilter {
    /// Current output value
    pub output: f64,
    /// Target value we're transitioning to
    pub target: f64,
    /// Time when transition started
    pub start_time: f64,
    /// Time when transition ends
    pub end_time: f64,
    /// Initial value at start of transition
    pub start_value: f64,
}

impl TransitionFilter {
    pub fn new() -> Self {
        Self {
            output: 0.0,
            target: 0.0,
            start_time: 0.0,
            end_time: 0.0,
            start_value: 0.0,
        }
    }

    /// Update the filter with new input and return filtered output
    pub fn update(
        &mut self,
        input: f64,
        time: f64,
        delay: f64,
        rise_time: f64,
        fall_time: f64,
    ) -> f64 {
        // Check if input target changed
        if (input - self.target).abs() > 1e-15 {
            // New transition started
            let trans_time = if input > self.output {
                rise_time
            } else {
                fall_time
            };
            self.target = input;
            self.start_value = self.output;
            self.start_time = time + delay;
            self.end_time = self.start_time + trans_time;
        }

        // Compute output based on current transition state
        if time < self.start_time {
            // Before transition starts
            self.output
        } else if time >= self.end_time || (self.end_time - self.start_time).abs() < 1e-15 {
            // Transition complete or instantaneous
            self.output = self.target;
            self.target
        } else {
            // In transition - linear interpolation
            let t = (time - self.start_time) / (self.end_time - self.start_time);
            self.output = self.start_value + t * (self.target - self.start_value);
            self.output
        }
    }
}

impl Default for TransitionFilter {
    fn default() -> Self {
        Self::new()
    }
}

/// Slew rate filter for limiting rate of change
#[derive(Debug, Clone)]
pub struct SlewFilter {
    /// Current output value
    pub output: f64,
    /// Previous time
    pub prev_time: f64,
}

impl SlewFilter {
    pub fn new() -> Self {
        Self {
            output: 0.0,
            prev_time: 0.0,
        }
    }

    /// Update the filter with new input, limiting slew rate
    pub fn update(&mut self, input: f64, time: f64, max_pos_slew: f64, max_neg_slew: f64) -> f64 {
        let dt = time - self.prev_time;
        if dt <= 0.0 {
            return self.output;
        }

        let delta = input - self.output;
        let rate = delta / dt;

        // Apply slew rate limiting
        let limited_rate = if rate > max_pos_slew {
            max_pos_slew
        } else if rate < -max_neg_slew {
            -max_neg_slew
        } else {
            rate
        };

        self.output += limited_rate * dt;
        self.prev_time = time;
        self.output
    }
}

impl Default for SlewFilter {
    fn default() -> Self {
        Self::new()
    }
}

/// Cross detector for threshold crossing events
#[derive(Debug, Clone)]
pub struct CrossDetector {
    /// Previous value
    pub prev_value: f64,
    /// Previous time
    pub prev_time: f64,
}

impl CrossDetector {
    pub fn new() -> Self {
        Self {
            prev_value: 0.0,
            prev_time: 0.0,
        }
    }

    /// Check for zero crossing, returns 1.0 if crossed, 0.0 otherwise
    /// direction: +1 = rising only, -1 = falling only, 0 = both
    pub fn update(&mut self, value: f64, time: f64, direction: i32) -> f64 {
        let result = if time == self.prev_time {
            0.0 // First call
        } else {
            let crossed = match direction {
                1 => self.prev_value < 0.0 && value >= 0.0,  // Rising
                -1 => self.prev_value > 0.0 && value <= 0.0, // Falling
                _ => {
                    (self.prev_value < 0.0 && value >= 0.0)
                        || (self.prev_value > 0.0 && value <= 0.0)
                }
            };
            if crossed {
                1.0
            } else {
                0.0
            }
        };

        self.prev_value = value;
        self.prev_time = time;
        result
    }
}

impl Default for CrossDetector {
    fn default() -> Self {
        Self::new()
    }
}

impl Default for VmContext {
    fn default() -> Self {
        Self {
            voltages: Vec::new(),
            internal_voltages: Vec::new(),
            currents: Vec::new(),
            terminal_pair_currents: Vec::new(),
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15, // 27°C default
            state_values: Vec::new(),
            state_values_prev: Vec::new(),
            timestep: 0.0,
            lookup_tables: Vec::new(),
            delay_buffers: Vec::new(),
            analysis_type: 0, // DC by default
            laplace_filters: Vec::new(),
        }
    }
}

impl VmContext {
    /// Create a new VM context with specified terminal count
    pub fn new(num_terminals: usize) -> Self {
        Self {
            voltages: vec![0.0; num_terminals],
            internal_voltages: Vec::new(),
            currents: Vec::new(),
            terminal_pair_currents: vec![f64::NAN; num_terminals.saturating_mul(num_terminals)],
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15,
            state_values: Vec::new(),
            state_values_prev: Vec::new(),
            timestep: 0.0,
            lookup_tables: Vec::new(),
            delay_buffers: Vec::new(),
            analysis_type: 0,
            laplace_filters: Vec::new(),
        }
    }

    /// Create with internal nodes
    pub fn with_internal_nodes(num_terminals: usize, num_internal: usize) -> Self {
        Self {
            voltages: vec![0.0; num_terminals],
            internal_voltages: vec![0.0; num_internal],
            currents: Vec::new(),
            terminal_pair_currents: vec![f64::NAN; num_terminals.saturating_mul(num_terminals)],
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15,
            state_values: Vec::new(),
            state_values_prev: Vec::new(),
            timestep: 0.0,
            lookup_tables: Vec::new(),
            delay_buffers: Vec::new(),
            analysis_type: 0,
            laplace_filters: Vec::new(),
        }
    }

    /// Create with state variables for transient analysis
    pub fn with_states(num_terminals: usize, num_states: usize) -> Self {
        Self {
            voltages: vec![0.0; num_terminals],
            internal_voltages: Vec::new(),
            currents: Vec::new(),
            terminal_pair_currents: vec![f64::NAN; num_terminals.saturating_mul(num_terminals)],
            parameters: Vec::new(),
            variables: Vec::new(),
            time: 0.0,
            temperature: 300.15,
            state_values: vec![0.0; num_states],
            state_values_prev: vec![0.0; num_states],
            timestep: 0.0,
            lookup_tables: Vec::new(),
            delay_buffers: Vec::new(),
            analysis_type: 0,
            laplace_filters: Vec::new(),
        }
    }

    /// Advance state for a new timestep (copy current to prev)
    pub fn advance_state(&mut self) {
        self.state_values_prev.clone_from(&self.state_values);
    }

    /// Set the timestep for transient analysis
    pub fn set_timestep(&mut self, dt: f64) {
        self.timestep = dt;
    }

    /// Allocate state variables
    pub fn allocate_states(&mut self, count: usize) {
        self.state_values.resize(count, 0.0);
        self.state_values_prev.resize(count, 0.0);
    }

    /// Clear cached branch current values.
    pub fn clear_currents(&mut self) {
        self.currents.clear();
        self.terminal_pair_currents.fill(f64::NAN);
    }

    /// Set branch current from `pos` to `neg`.
    ///
    /// Also populates the reverse direction with opposite sign.
    pub fn set_branch_current(&mut self, pos: usize, neg: usize, value: f64) {
        let n = self.voltages.len();
        if n == 0 || pos >= n || neg >= n {
            return;
        }

        if self.terminal_pair_currents.len() != n.saturating_mul(n) {
            self.terminal_pair_currents
                .resize(n.saturating_mul(n), f64::NAN);
        }

        let idx = pos * n + neg;
        self.terminal_pair_currents[idx] = value;

        if pos != neg {
            let reverse_idx = neg * n + pos;
            self.terminal_pair_currents[reverse_idx] = -value;
        }
    }

    /// Get the voltage difference between two terminals
    #[inline]
    pub fn voltage(&self, pos: usize, neg: usize) -> f64 {
        let v_pos = self.voltages.get(pos).copied().unwrap_or(0.0);
        let v_neg = self.voltages.get(neg).copied().unwrap_or(0.0);
        v_pos - v_neg
    }

    /// Get internal node voltage
    #[inline]
    pub fn internal_voltage(&self, idx: usize) -> f64 {
        self.internal_voltages.get(idx).copied().unwrap_or(0.0)
    }

    /// Get current between terminals.
    #[inline]
    pub fn current(&self, pos: usize, neg: usize) -> f64 {
        let n = self.voltages.len();
        if pos < n && neg < n {
            let idx = pos * n + neg;
            if idx < self.terminal_pair_currents.len() {
                let value = self.terminal_pair_currents[idx];
                if value.is_finite() {
                    return value;
                }
            }
        }
        self.currents.first().copied().unwrap_or(0.0)
    }

    /// Get pointer to the terminal-pair current lookup buffer.
    #[inline]
    pub fn terminal_pair_currents_ptr(&self) -> *const f64 {
        self.terminal_pair_currents.as_ptr()
    }

    /// Get length of the terminal-pair current lookup buffer.
    #[inline]
    pub fn terminal_pair_currents_len(&self) -> usize {
        self.terminal_pair_currents.len()
    }

    /// Get number of terminals in this context.
    #[inline]
    pub fn terminal_count(&self) -> usize {
        self.voltages.len()
    }

    /// Get thermal voltage kT/q
    #[inline]
    pub fn vt(&self) -> f64 {
        const K_BOLTZMANN: f64 = 1.380649e-23;
        const Q_ELECTRON: f64 = 1.602176634e-19;
        K_BOLTZMANN * self.temperature / Q_ELECTRON
    }

    /// Set a parameter value
    pub fn set_param(&mut self, index: usize, value: f64) {
        if index >= self.parameters.len() {
            self.parameters.resize(index + 1, 0.0);
        }
        self.parameters[index] = value;
    }

    /// Set a variable value
    pub fn set_variable(&mut self, index: usize, value: f64) {
        if index >= self.variables.len() {
            self.variables.resize(index + 1, 0.0);
        }
        self.variables[index] = value;
    }
}

/// Stack-based virtual machine for bytecode execution
pub struct Vm<'a> {
    /// Execution context
    pub context: &'a mut VmContext,
    /// Evaluation stack
    pub stack: Vec<f64>,
}

impl<'a> Vm<'a> {
    /// Create a new VM with the given context
    pub fn new(context: &'a mut VmContext) -> Self {
        Self {
            context,
            stack: Vec::with_capacity(32),
        }
    }

    /// Execute a bytecode program and return the result
    pub fn execute(&mut self, program: &BytecodeProgram) -> Result<f64, VmError> {
        self.stack.clear();

        for instruction in &program.instructions {
            self.execute_instruction(instruction)?;
        }

        self.stack
            .pop()
            .ok_or(VmError::StackUnderflow("No result on stack"))
    }

    /// Execute a single instruction
    #[inline]
    fn execute_instruction(&mut self, instruction: &Instruction) -> Result<(), VmError> {
        match instruction {
            Instruction::PushConst(v) => {
                self.stack.push(*v);
            }
            Instruction::PushParam(idx) => {
                let v = self.context.parameters.get(*idx).copied().unwrap_or(0.0);
                self.stack.push(v);
            }
            Instruction::PushVoltage(pos, neg) => {
                self.stack.push(self.context.voltage(*pos, *neg));
            }
            Instruction::PushCurrent(pos, neg) => {
                self.stack.push(self.context.current(*pos, *neg));
            }
            Instruction::PushInternalVoltage(idx) => {
                self.stack.push(self.context.internal_voltage(*idx));
            }
            Instruction::PushVariable(idx) => {
                let v = self.context.variables.get(*idx).copied().unwrap_or(0.0);
                self.stack.push(v);
            }
            Instruction::PushTime => {
                self.stack.push(self.context.time);
            }
            Instruction::PushTemperature => {
                self.stack.push(self.context.temperature);
            }
            Instruction::PushVt => {
                self.stack.push(self.context.vt());
            }

            // Binary operations
            Instruction::Add => self.binary_op(|a, b| a + b)?,
            Instruction::Sub => self.binary_op(|a, b| a - b)?,
            Instruction::Mul => self.binary_op(|a, b| a * b)?,
            Instruction::Div => self.binary_op(|a, b| a / b)?,
            Instruction::Pow => self.binary_op(|a, b| a.powf(b))?,

            // Unary operations
            Instruction::Neg => self.unary_op(|a| -a)?,
            Instruction::Abs => self.unary_op(|a| a.abs())?,
            Instruction::Sqrt => self.unary_op(|a| a.sqrt())?,
            Instruction::Exp => self.unary_op(|a| a.exp())?,
            Instruction::Log => self.unary_op(|a| a.ln())?,
            Instruction::Log10 => self.unary_op(|a| a.log10())?,
            Instruction::Sin => self.unary_op(|a| a.sin())?,
            Instruction::Cos => self.unary_op(|a| a.cos())?,
            Instruction::Tan => self.unary_op(|a| a.tan())?,
            Instruction::Sinh => self.unary_op(|a| a.sinh())?,
            Instruction::Cosh => self.unary_op(|a| a.cosh())?,
            Instruction::Tanh => self.unary_op(|a| a.tanh())?,

            // Two-argument functions
            Instruction::Min => self.binary_op(|a, b| a.min(b))?,
            Instruction::Max => self.binary_op(|a, b| a.max(b))?,

            // Limited exponential for convergence
            // Uses linear extrapolation beyond the limit to prevent overflow
            // while maintaining C0 and C1 continuity
            Instruction::Limexp => self.unary_op(|a| {
                const LIMIT: f64 = 40.0; // exp(40) ≈ 2.4e17
                if a > LIMIT {
                    let exp_limit = LIMIT.exp();
                    // Linear extrapolation: f(x) = f(limit) + f'(limit) * (x - limit)
                    // For exp, f'(x) = exp(x), so f'(limit) = exp(limit)
                    exp_limit * (1.0 + a - LIMIT)
                } else if a < -LIMIT {
                    // For very negative values, return essentially 0
                    (-LIMIT).exp()
                } else {
                    a.exp()
                }
            })?,

            // Inverse trigonometric functions
            Instruction::Asin => self.unary_op(|a| a.asin())?,
            Instruction::Acos => self.unary_op(|a| a.acos())?,
            Instruction::Atan => self.unary_op(|a| a.atan())?,
            Instruction::Atan2 => self.binary_op(|y, x| y.atan2(x))?,

            // Rounding functions
            Instruction::Floor => self.unary_op(|a| a.floor())?,
            Instruction::Ceil => self.unary_op(|a| a.ceil())?,

            // Power function (2-argument: base^exponent)
            Instruction::FnPow => self.binary_op(|base, exp| base.powf(exp))?,

            // Conditional: if cond != 0, use then_val, else else_val
            Instruction::IfElse => {
                let else_val = self.pop()?;
                let then_val = self.pop()?;
                let cond = self.pop()?;
                let result = if cond.abs() > 1e-15 {
                    then_val
                } else {
                    else_val
                };
                self.stack.push(result);
            }

            // Comparison operations (return 1.0 for true, 0.0 for false)
            Instruction::Gt => self.binary_op(|a, b| if a > b { 1.0 } else { 0.0 })?,
            Instruction::Lt => self.binary_op(|a, b| if a < b { 1.0 } else { 0.0 })?,
            Instruction::Ge => self.binary_op(|a, b| if a >= b { 1.0 } else { 0.0 })?,
            Instruction::Le => self.binary_op(|a, b| if a <= b { 1.0 } else { 0.0 })?,
            Instruction::Eq => {
                self.binary_op(|a, b| if (a - b).abs() < 1e-15 { 1.0 } else { 0.0 })?
            }
            Instruction::Ne => {
                self.binary_op(|a, b| if (a - b).abs() >= 1e-15 { 1.0 } else { 0.0 })?
            }

            // Logical operations
            Instruction::And => self.binary_op(|a, b| {
                if a.abs() > 1e-15 && b.abs() > 1e-15 {
                    1.0
                } else {
                    0.0
                }
            })?,
            Instruction::Or => self.binary_op(|a, b| {
                if a.abs() > 1e-15 || b.abs() > 1e-15 {
                    1.0
                } else {
                    0.0
                }
            })?,
            Instruction::Not => self.unary_op(|a| if a.abs() < 1e-15 { 1.0 } else { 0.0 })?,

            // State-based ddt: (current_expr - prev_state) / dt
            // The expression value is on the stack, we save it and compute derivative
            Instruction::DdtState(idx) => {
                let current_value = self.pop()?;
                let prev_value = self
                    .context
                    .state_values_prev
                    .get(*idx)
                    .copied()
                    .unwrap_or(current_value);

                // Save current value for next timestep
                if *idx < self.context.state_values.len() {
                    // Note: We can't mutate context here since it's borrowed
                    // The device layer should handle state updates
                }

                // Compute derivative: (current - prev) / dt
                // For DC analysis (dt=0), return 0
                let dt = self.context.timestep;
                let derivative = if dt.abs() > 1e-20 {
                    (current_value - prev_value) / dt
                } else {
                    0.0 // DC analysis: ddt = 0
                };
                self.stack.push(derivative);
            }

            // State-based idt: prev_state + expr * dt
            // Accumulates the integral over time
            Instruction::IdtState(idx) => {
                let current_value = self.pop()?;
                let prev_integral = self
                    .context
                    .state_values_prev
                    .get(*idx)
                    .copied()
                    .unwrap_or(0.0);

                let dt = self.context.timestep;
                // Forward Euler: integral += expr * dt
                let new_integral = if dt.abs() > 1e-20 {
                    prev_integral + current_value * dt
                } else {
                    prev_integral // DC: use accumulated value
                };
                self.stack.push(new_integral);
            }

            // $limit function: bounds value change per Newton iteration
            // Stack: [new_value, step_limit] -> [limited_value]
            // Uses state to track previous iteration value
            Instruction::LimitState(idx) => {
                let step_limit = self.pop()?;
                let new_value = self.pop()?;

                // Get previous value from state (or use new_value if first iteration)
                let prev_value = self
                    .context
                    .state_values_prev
                    .get(*idx)
                    .copied()
                    .unwrap_or(new_value);

                // Compute the change from previous iteration
                let delta = new_value - prev_value;

                // Clamp the delta to within [-step_limit, +step_limit]
                let limited_delta = if delta > step_limit {
                    step_limit
                } else if delta < -step_limit {
                    -step_limit
                } else {
                    delta
                };

                // Compute limited value
                let limited_value = prev_value + limited_delta;
                self.stack.push(limited_value);
            }

            // TableLookup: linear interpolation in lookup table
            // Stack: [input_value] -> [interpolated_value]
            // Uses context.lookup_tables for table storage
            Instruction::TableLookup(table_id) => {
                let input = self.pop()?;

                // Get the lookup table from context
                let result = if let Some(table) = self.context.lookup_tables.get(*table_id) {
                    // Use the commercial-grade LookupTable interpolation
                    table.interpolate(input)
                } else {
                    // Table not found - return 0 with warning
                    // In production, this should be caught at compile time
                    0.0
                };

                self.stack.push(result);
            }

            // AbsDelayState: transport delay with circular buffer
            // Stack: [expr_value, delay_time] -> [delayed_value]
            // Uses context.delay_buffers for storage
            Instruction::AbsDelayState(buffer_id) => {
                let delay_time = self.pop()?;
                let current_value = self.pop()?;
                let current_time = self.context.time;

                // Get or create the delay buffer
                // Note: In practice, delay_buffers should be pre-allocated
                // For DC analysis, absdelay returns current value (no delay)
                let result = if delay_time <= 0.0 || current_time == 0.0 {
                    current_value
                } else if let Some(buffer) = self.context.delay_buffers.get(*buffer_id) {
                    buffer.get_delayed(current_time, delay_time)
                } else {
                    // Buffer not found - return current value
                    current_value
                };

                self.stack.push(result);
            }

            // TransitionState: piecewise-linear signal smoothing
            // Stack: [expr, delay, rise_time, fall_time] -> [filtered]
            Instruction::TransitionState(_filter_id) => {
                let fall_time = self.pop()?;
                let rise_time = self.pop()?;
                let _delay = self.pop()?;
                let input = self.pop()?;
                let _time = self.context.time;

                // For DC analysis or when times are 0, use instantaneous
                let result = if rise_time <= 0.0 && fall_time <= 0.0 {
                    input
                } else {
                    // Simplified: in steady-state, output equals input
                    // Full implementation would use TransitionFilter state
                    input
                };

                self.stack.push(result);
            }

            // SlewState: slew rate limiting
            // Stack: [expr, max_pos_slew, max_neg_slew] -> [limited]
            Instruction::SlewState(_filter_id) => {
                let max_neg_slew = self.pop()?;
                let max_pos_slew = self.pop()?;
                let input = self.pop()?;

                // For DC analysis or infinite slew, pass through
                let result = if max_pos_slew.is_infinite() && max_neg_slew.is_infinite() {
                    input
                } else {
                    // Simplified: in steady-state, output equals input
                    input
                };

                self.stack.push(result);
            }

            // CrossState: threshold crossing detection
            // Stack: [expr, direction] -> [0 or 1]
            Instruction::CrossState(_detector_id) => {
                let direction = self.pop()?;
                let value = self.pop()?;

                // For DC analysis, cross never fires
                // Returns 1.0 only during transient when crossing occurs
                let result = if self.context.time == 0.0 {
                    0.0
                } else {
                    // Simplified: DC returns 0
                    let _ = (value, direction);
                    0.0
                };

                self.stack.push(result);
            }

            // WhiteNoise: white noise source
            // Stack: [power] -> [0]
            // In time domain, noise returns 0
            Instruction::WhiteNoise => {
                let _power = self.pop()?;
                // Noise contributes to AC noise analysis, not time domain
                self.stack.push(0.0);
            }

            // FlickerNoise: 1/f flicker noise
            // Stack: [power, exponent] -> [0]
            Instruction::FlickerNoise => {
                let _exponent = self.pop()?;
                let _power = self.pop()?;
                // Noise contributes to AC noise analysis, not time domain
                self.stack.push(0.0);
            }

            // Analysis: check current analysis type
            // Stack: [] -> [0 or 1]
            // analysis_type encoding: 0=dc, 1=ac, 2=tran, 3=noise
            Instruction::Analysis(analysis_str_id) => {
                let current_type = self.context.analysis_type;
                let result = match analysis_str_id {
                    0 => {
                        // "dc" check
                        if current_type == 0 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    1 => {
                        // "ac" check
                        if current_type == 1 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    2 => {
                        // "tran" check
                        if current_type == 2 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    3 => {
                        // "noise" check
                        if current_type == 3 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    _ => 0.0, // Unknown analysis type
                };
                self.stack.push(result);
            }

            // AboveState: level crossing event detection
            // Stack: [expr, threshold] -> [0 or 1]
            Instruction::AboveState(_detector_id) => {
                let threshold = self.pop()?;
                let value = self.pop()?;
                // For DC analysis, simply check if value > threshold
                // In transient, this would generate events on crossing
                let result = if value > threshold { 1.0 } else { 0.0 };
                self.stack.push(result);
            }

            // TimerState: periodic timer event
            // Stack: [start_time, period] -> [0 or 1]
            Instruction::TimerState(_timer_id) => {
                let period = self.pop()?;
                let start_time = self.pop()?;
                let current_time = self.context.time;

                // Timer fires when: time >= start_time AND
                // (time - start_time) is at a multiple of period
                let result = if current_time >= start_time && period > 0.0 {
                    let elapsed = current_time - start_time;
                    let cycles = (elapsed / period).floor();
                    let next_fire = start_time + cycles * period;
                    // Check if current time is at (or very close to) a fire point
                    let tolerance = self.context.timestep.max(1e-15);
                    if (current_time - next_fire).abs() < tolerance {
                        1.0
                    } else {
                        0.0
                    }
                } else {
                    0.0
                };
                self.stack.push(result);
            }

            // LaplaceState: Laplace transfer function (both ZP and ND forms)
            // Stack: [input] -> [filtered_output]
            Instruction::LaplaceState(filter_id) => {
                let input = self.pop()?;
                let result = if self.context.analysis_type == 2 {
                    // Transient analysis
                    if let Some(filter) = self.context.laplace_filters.get_mut(*filter_id) {
                        filter.step(input, self.context.timestep)
                    } else {
                        input
                    }
                } else {
                    // DC and others (s=0)
                    if let Some(filter) = self.context.laplace_filters.get(*filter_id) {
                        filter.dc_output(input)
                    } else {
                        input
                    }
                };
                self.stack.push(result);
            }
        }
        Ok(())
    }

    /// Pop a value from the stack
    #[inline]
    fn pop(&mut self) -> Result<f64, VmError> {
        self.stack
            .pop()
            .ok_or(VmError::StackUnderflow("Stack underflow"))
    }

    /// Apply a unary operation
    #[inline]
    fn unary_op<F>(&mut self, f: F) -> Result<(), VmError>
    where
        F: FnOnce(f64) -> f64,
    {
        let a = self.pop()?;
        self.stack.push(f(a));
        Ok(())
    }

    /// Apply a binary operation
    #[inline]
    fn binary_op<F>(&mut self, f: F) -> Result<(), VmError>
    where
        F: FnOnce(f64, f64) -> f64,
    {
        let b = self.pop()?;
        let a = self.pop()?;
        self.stack.push(f(a, b));
        Ok(())
    }
}

/// VM execution errors
#[derive(Debug, Clone, PartialEq)]
pub enum VmError {
    StackUnderflow(&'static str),
    InvalidInstruction(&'static str),
}

impl std::fmt::Display for VmError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            VmError::StackUnderflow(msg) => write!(f, "Stack underflow: {}", msg),
            VmError::InvalidInstruction(msg) => write!(f, "Invalid instruction: {}", msg),
        }
    }
}

impl std::error::Error for VmError {}

